  ('84f36e23-48c8-58da-91f6-c1ac44888664', 'math', 'algebra', 1, 'mcq', 'If x + 5 = 12, what is x?', '{"correct":"B"}'),
  ('774f3e8b-381c-5c46-9383-c36be5373495', 'math', 'algebra', 1, 'mcq', 'If 3x = 18, what is x?', '{"correct":"B"}'),
  ('f5e501a1-c2ee-57bf-8d6a-92f7afa03543', 'math', 'algebra', 2, 'mcq', 'The system x + y = 10 and x - y = 4. What is x?', '{"correct":"C"}'),
  ('e8be225d-7e35-53c7-b1a5-90331b49049b', 'math', 'geometry', 1, 'mcq', 'A rectangle has length 8 and width 3. What is the area?', '{"correct":"C"}'),
  ('b9fa1998-6026-5f91-bb0d-b6d5fb4968c9', 'math', 'geometry', 1, 'mcq', 'A triangle has base 10 and height 6. What is the area?', '{"correct":"B"}'),
  ('311fa78c-5804-549a-9d72-2a63ae429837', 'math', 'ratios', 2, 'mcq', 'A ratio of boys to girls is 3 to 5. If there are 24 students, how many are girls?', '{"correct":"C"}'),
  ('cb5165ee-6f70-5701-844d-f8b7e6453c72', 'math', 'percent', 2, 'mcq', 'A price of 50 is increased by 20 percent. What is the new price?', '{"correct":"B"}'),
  ('49daaf64-1888-57a4-85d6-a871d8e226ec', 'math', 'functions', 2, 'mcq', 'If f(x) = 2x + 1, what is f(4)?', '{"correct":"C"}'),
  ('24ba46ea-2ca5-509d-a5d1-2d7abaf4b1f6', 'math', 'data', 2, 'mcq', 'What is the mean of 4, 6, and 10?', '{"correct":"C"}'),
  ('9fd69296-72b1-59d6-bc27-dd2249316acf', 'math', 'inequalities', 2, 'mcq', 'Solve x - 3 > 2. Which value satisfies the inequality?', '{"correct":"C"}'),
